-                            Thread.sleep(intervalMillis);
-                        }
-                    } catch (InterruptedException ie) {
-                        Thread.currentThread().interrupt();
-                        ie.addSuppressed(e);
-                        throw new RuntimeException(ie);
-                    }
-                } else {
+                if (attemptsCount <= 0) {
                     throw e;
                 }
+                sleepBetweenAttempts(intervalMillis, e);
             }
