@@ -28,6 +28,63 @@ import org.junit.jupiter.api.Test;

 class RetryTest {

+    @Test
+    void executeShouldReturnZeroWhenFirstAttemptSucceeds() {
+        AtomicInteger attempts = new AtomicInteger(0);
+        int firstSuccess = Retry.execute(attempts::incrementAndGet, 3, 0);
+        Assertions.assertEquals(0, firstSuccess);
+        Assertions.assertEquals(1, attempts.get());
+    }
+
+    @Test
+    void executeShouldReturnIndexOfFirstSuccessfulAttempt() {
+        AtomicInteger attempts = new AtomicInteger(0);
+        int firstSuccess = Retry.execute(() -> {
+            if (attempts.getAndIncrement() < 2) {
+                throw new RuntimeException("not yet");
+            }
+        }, 5, 0);
+        Assertions.assertEquals(2, firstSuccess);
+        Assertions.assertEquals(3, attempts.get());
+    }
+
+    @Test
+    void executeShouldRethrowLastFailureAfterExhaustingAttempts() {
+        AtomicInteger attempts = new AtomicInteger(0);
+        IllegalStateException thrown = Assertions.assertThrowsExactly(IllegalStateException.class, () ->
+                Retry.execute(() -> {
+                    attempts.incrementAndGet();
+                    throw new IllegalStateException("always fails");
+                }, 3, 0));
+        Assertions.assertEquals("always fails", thrown.getMessage());
+        Assertions.assertEquals(3, attempts.get());
+    }
+
+    @Test
+    void callShouldReturnSupplierValueAfterRetrying() {
+        AtomicInteger attempts = new AtomicInteger(0);
+        String result = Retry.call(iteration -> {
+            if (attempts.getAndIncrement() < 1) {
+                throw new RuntimeException("not yet");
+            }
+            return "value-" + iteration;
+        }, 3, 0);
+        Assertions.assertEquals("value-1", result);
+        Assertions.assertEquals(2, attempts.get());
+    }
+
